from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.cu.services.internal.trs.http_client_v2 import TRSv2HttpClient
from taf.gnb.oam.coam.cu.services.internal.trs.http_client_v1 import TRSv1HttpClient
from taf.gnb.oam.coam.cu.utilities.poll_status import poll_status


@auto_token_refresh()
class TRSv2:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = TRSv2HttpClient(base_url=con_details.base_url,
                                            connection_alias=con_details.alias)
        self.local_client_v1 = TRSv1HttpClient(base_url=con_details.base_url,
                                               connection_alias=con_details.alias)

    def generate_csr_for_ne(self, timeout=30, key_pool_type='RSA'):
        operation_id = self.local_client.generate_csr_for_ne(key_pool_type=key_pool_type)

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def get_csr_file(self, timeout=30, key_pool_type='RSA'):
        return self.local_client.get_csr_file(key_pool_type=key_pool_type, timeout=timeout)

    def install_operators_certificate(self, certificate_file_path, certificate_type, timeout=30):
        operation_id = self.local_client.install_operators_certificate(certificate_file_path=certificate_file_path,
                                                                       certificate_type=certificate_type)

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def get_operator_certificate_list(self, timeout=30):
        return self.local_client.get_operator_certificate_list(timeout=timeout)

    def delete_all_operator_certificates(self, timeout=30):
        operation_id = self.local_client.delete_all_operator_certificates()

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def get_operator_certificate(self, certificate_id, timeout=30):
        return self.local_client.get_operator_certificate(certificate_id=certificate_id, timeout=timeout)

    def delete_operator_certificate(self, certificate_id, timeout=30):
        operation_id = self.local_client.delete_operator_certificate(certificate_id=certificate_id)

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def trigger_certificate_initialization(self, timeout=30, key_pool_type='RSA'):
        operation_id =  self.local_client.trigger_certificate_initialization(key_pool_type=key_pool_type)

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def trigger_cmp_server_key_update(self, timeout=30, key_pool_type='RSA'):
        operation_id = self.local_client.trigger_cmp_server_key_update(key_pool_type=key_pool_type)

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def update_cmp_server_settings(self, ref_number, psk_key, timeout=30, key_pool_type='RSA'):
        operation_id = self.local_client.update_cmp_server_settings(ref_number=ref_number,
                                                                    psk_key=psk_key,
                                                                    key_pool_type=key_pool_type)

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def trigger_crl_information_update(self, timeout=30):
        operation_id = self.local_client.trigger_crl_information_update()

        return poll_status(instance=self.local_client_v1,
                           method_name="get_trs_operation_status",
                           timeout=timeout,
                           operation_id=operation_id)

    def get_current_crl(self, timeout=30):
        return self.local_client.get_current_crl(timeout=timeout)
